<script>
(()=>{const RM=matchMedia("(prefers-reduced-motion: reduce)").matches;
const vis=e=>e&&e.offsetParent!==null;
const ptr=z=>{const p=z.querySelector(":scope>.xapt");if(!p||RM||!z.offsetWidth)return;const D=+z.dataset.d||8,R=z.getBoundingClientRect();
const pts=z.dataset.p.split(",").map(x=>{const [sel,pc]=x.split("@");const e=z.querySelector(sel);if(!e)return null;const r=e.getBoundingClientRect();return[r.left-R.left+r.width*.5,r.top-R.top+r.height*.55,+pc]}).filter(Boolean);if(!pts.length)return;
const id="xap"+Math.round(R.width)+"x"+Math.round(R.height)+"x"+pts.map(q=>Math.round(q[0])+"_"+Math.round(q[1])).join("_");if(p.dataset.k===id)return;p.dataset.k=id;
const S=[R.width*.92,R.height+12],T=(q,s)=>`transform:translate(${q[0].toFixed(1)}px,${q[1].toFixed(1)}px)${s?" scale("+s+")":""}`;
let k=`0%{${T(S)};opacity:0}`,prev=0;
pts.forEach((q,i)=>{const a=q[2];if(i===0)k+=`${Math.max(3,a-20)}%{${T(S)};opacity:1}`;else{const h=Math.max(prev+4,a-14);if(h>prev)k+=`${h}%{${T(pts[i-1])}}`}k+=`${a}%{${T(q)}}${a+1}%{${T(q,.8)}}${a+2.5}%{${T(q)}}`;prev=a+2.5});
const L=pts[pts.length-1];k+=`${Math.min(prev+8,88)}%{${T(L)};opacity:1}${Math.min(prev+18,96)}%{${T(S)};opacity:0}100%{${T(S)};opacity:0}`;
let st=z.querySelector(":scope>style.xapk");if(!st){st=document.createElement("style");st.className="xapk";z.appendChild(st)}st.textContent=`@keyframes ${id}{${k}}`;p.style.animation=`${id} ${D}s cubic-bezier(.45,0,.2,1) infinite`};
const fit=()=>{document.querySelectorAll(".xapz[data-p]").forEach(ptr)};
const typer=w=>{const el=w.querySelector(".xaty[data-t]");if(!el)return;const t=el.dataset.t,sp=t.length<24?110:40;w.classList.add("js");if(RM){w.classList.add("done");return}let i=0;el.textContent="";
const tick=()=>{if(!vis(el)){i=0;el.textContent="";w.classList.remove("done");return setTimeout(tick,600)}if(i<=t.length){el.textContent=t.slice(0,i);i++;if(i>t.length){w.classList.add("done");setTimeout(tick,4200)}else setTimeout(tick,sp+Math.random()*sp)}else{i=0;el.textContent="";w.classList.remove("done");setTimeout(tick,800)}};setTimeout(tick,900)};
const typer2=el=>{const t=el.dataset.t;if(RM)return;let i=0;el.textContent="";const tick=()=>{if(!vis(el)){i=0;el.textContent="";return setTimeout(tick,700)}if(i<=t.length){el.textContent=t.slice(0,i);i++;setTimeout(tick,i>t.length?2800:75)}else{i=0;el.textContent="";setTimeout(tick,900)}};setTimeout(tick,2600)};
const ghost=()=>document.querySelectorAll(".xaty[data-t],.xaty2[data-t]").forEach(el=>{const p=el.parentElement;if(p.classList.contains("xagr"))return;const l=document.createElement("span");l.className="xawrt";const c=el.nextElementSibling&&el.nextElementSibling.classList.contains("caret")?el.nextElementSibling:null;p.insertBefore(l,el);l.appendChild(el);if(c)l.appendChild(c);const g=document.createElement("span");g.className="xaghost";g.setAttribute("aria-hidden","true");g.textContent=el.dataset.t;p.appendChild(g);p.classList.add("xagr")});
document.addEventListener("DOMContentLoaded",()=>{ghost();fit();document.querySelectorAll(".xatyw").forEach(typer);document.querySelectorAll(".xaty2[data-t]").forEach(typer2)});
addEventListener("load",fit);addEventListener("resize",fit);document.addEventListener("click",()=>setTimeout(fit,60));document.addEventListener("input",()=>setTimeout(fit,60));
if(document.fonts)document.fonts.ready.then(fit)})();
</script>
<script>(()=>{const f=()=>document.querySelectorAll(".crmv[data-to]").forEach(m=>{const w=m.closest("[data-tw]"),t=w&&w.querySelector(m.dataset.to);if(!t||!m.offsetWidth)return;if(!m.querySelector(".crpt"))m.insertAdjacentHTML("beforeend","<svg class=crpt viewBox=\"0 0 16 16\" aria-hidden=true><path d=\"M2 1l11 6-5 1.5L6 14z\" fill=\"#0f172a\" stroke=\"#fff\" stroke-width=\"1.2\" stroke-linejoin=round /></svg>");m.style.animation=t.style.animation="none";const M=m.getBoundingClientRect(),R=t.getBoundingClientRect();m.style.animation=t.style.animation="";m.style.setProperty("--dx",Math.round(R.left-M.left)+"px");m.style.setProperty("--dy",Math.round(R.top-M.top)+"px")});document.addEventListener("DOMContentLoaded",f);addEventListener("load",f);addEventListener("resize",f);document.addEventListener("click",()=>setTimeout(f,60));document.addEventListener("input",()=>setTimeout(f,60));if(document.fonts)document.fonts.ready.then(f)})();</script>
